import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { api, apiUrl, ENDPOINTS, isMockApi, atyabLog } from "../api.js";

function normalize(raw, id) {
  const r = raw || {};
  return {
    id: Number(r.productId) || Number(id) || 0,
    desc: r.productDescriptionAr || "",
    descEn: r.productDescriptionEn || "",
    story: r.storyAr || "",
    storyEn: r.storyEn || "",
    top: r.scentTopAr || "", topEn: r.scentTopEn || "",
    heart: r.scentHeartAr || "", heartEn: r.scentHeartEn || "",
    base: r.scentBaseAr || "", baseEn: r.scentBaseEn || "",
    updatedAt: r.updatedAt || ""
  };
}

export const getProductProfile = createAsyncThunk(
  "profiles/getOne",
  async function (productId, { rejectWithValue }) {
    const id = Number(productId) || 0;
    try {
      atyabLog("profile FETCH", id);
      if (isMockApi()) return normalize({ productId: id }, id);
      const res = await api.get(apiUrl(ENDPOINTS.productProfile(id)));
      return normalize(res.data, id);
    } catch (err) {
      atyabLog("profile FAIL", id);
      return rejectWithValue("تعذر جلب تفاصيل المنتج");
    }
  },
  {
    condition: function (productId, { getState }) {
      const id = Number(productId) || 0;
      const s = getState().profiles;
      if (s && s.byId && s.byId[id]) { atyabLog("profile CACHE-HIT", id); return false; }
      if (s && s.failed && s.failed[id]) { atyabLog("profile KNOWN-404", id); return false; }
      if (s && s.loading && s.loading[id]) { atyabLog("profile IN-FLIGHT", id); return false; }
      atyabLog("profile MISS", id);
      return true;
    }
  }
);

const slice = createSlice({
  name: "profiles",
  initialState: { byId: {}, loading: {}, error: {}, failed: {} },
  reducers: {},
  extraReducers: function (builder) {
    builder
      .addCase(getProductProfile.pending, function (state, action) {
        state.loading[action.meta.arg] = true;
      })
      .addCase(getProductProfile.fulfilled, function (state, action) {
        const p = action.payload;
        state.loading[p.id] = false;
        state.byId[p.id] = p;
        atyabLog("profile CACHED", p.id);
      })
      .addCase(getProductProfile.rejected, function (state, action) {
        state.loading[action.meta.arg] = false;
        state.error[action.meta.arg] = action.payload || "fail";
        state.failed[action.meta.arg] = true;
        atyabLog("profile MARK-404", action.meta.arg);
      });
  }
});

export function selectProductProfile(state, id) {
  return (state.profiles && state.profiles.byId[Number(id)]) || null;
}
export function selectProfileLoading(state, id) {
  return !!(state.profiles && state.profiles.loading[Number(id)]);
}
export default slice.reducer;
