/* ------------------------------------------------------------
   نافذة الشروط والأحكام — مثل زر «اعرف قصته»: تُفتح بضغطة زر
   وتُغلق بالخلفية/×/Escape. تستعمل نفس هيكل .screen في الموقع.
   ------------------------------------------------------------ */
function TermsModal(props) {
  const language = props.language;
  useEffect(
    function () {
      function onKey(e) {
        if (e.key === "Escape") props.onClose();
      }
      document.addEventListener("keydown", onKey);
      return function () {
        document.removeEventListener("keydown", onKey);
      };
    },
    [props]
  );
  return (
    <div className="screen is-open" role="dialog" aria-modal="true" aria-labelledby="ckTermsTitle">
      <div className="screen-backdrop" onClick={props.onClose} />
      <div className="screen-panel">
        <div className="screen-head">
          <h2 id="ckTermsTitle">
            {T(ATYAB_TERMS.title, language)} · نسخة {ATYAB_TERMS.version}
          </h2>
          <button className="screen-close" type="button" aria-label="إغلاق" onClick={props.onClose}>
            <Icon name="x" strokeWidth={2} />
          </button>
        </div>
        <div className="screen-body">
          <p className="ck-hint">{T(ATYAB_TERMS.updated, language)}</p>
          <p className="story-text">{T(ATYAB_TERMS.intro, language)}</p>
          {ATYAB_TERMS.clauses.map(function (clause, i) {
            return (
              <p className="story-text" key={i}>
                <b>
                  {clause.n}. {T(clause.title, language)}
                </b>{" "}
                — {T(clause.body, language)}
              </p>
            );
          })}
          <p className="ck-hint">{T(ATYAB_TERMS.contact, language)}</p>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------
   صفحة إتمام الدفع
   ------------------------------------------------------------ */
export default function CheckoutPage() {
  usePageMeta({ route: "checkout", titleAr: "إتمام الطلب", titleEn: "Checkout" });

  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const totals = useAppSelector(selectCartTotals);
  const profile = useAppSelector(function (s) {
    return s.user.profile;
  });
  const session = useAppSelector(function (s) {
    return s.user.session;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const cartMethod = useAppSelector(function (s) {
    return s.cart.paymentMethod;
  });

  const [form, setForm] = useState(function () {
    const base = initialForm(profile);
    base.method = cartMethod || "";
    return base;
  });
  const [step, setStep] = useState(function () {
    return validateStep(form, "info").valid ? "pay" : "info";
  });
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  const [order, setOrder] = useState(null);
  const [termsOpen, setTermsOpen] = useState(false);
  const [infoEdit, setInfoEdit] = useState(false);
  const [syncBusy, setSyncBusy] = useState(false);
  const [serverAppliedCk, setServerAppliedCk] = useState(false);
  const customerId = useAppSelector(function (s) {
    return s.user.auth && s.user.auth.customerId;
  });
  const serverDetails = useAppSelector(function (s) {
    return s.customer.details;
  });
  const serverLocations = useAppSelector(selectCustomerLocations);
  const hasSaved = serverLocations.length > 0;
  const infoNeeded = !hasSaved || infoEdit;
  const visibleSteps = infoNeeded ? STEPS : STEPS.filter(function (s) { return s.key !== "info"; });

  useEffect(function () {
    if (customerId && session) dispatch(fetchCustomerData(Number(customerId)));
  }, [customerId, session, dispatch]);

  useEffect(function () {
    dispatch(loadGeo());
    dispatch(loadStoreSection("payments"));
    dispatch(loadStoreSection("shipping"));
  }, [dispatch]);

  const geo = useAppSelector(function (s) { return s.geo; });
  const appliedCoupon = useAppSelector(function (s) { return s.cart.coupon; });
  /* ★ معرّفات الخادم للطلب: الدفع من قائمة /api/payment-methods (id+key)،
     والتوصيل أول شركة من /api/shipping-carriers — بلا اختيار يدوي بعد. */
  const payItems = useAppSelector(function (s) { return (s.storeInfo && s.storeInfo.payments && s.storeInfo.payments.items) || []; });
  const shipItems = useAppSelector(function (s) { return (s.storeInfo && s.storeInfo.shipping && s.storeInfo.shipping.items) || []; });
  const carrier = shipItems.length ? shipItems[0] : null;
  const profileCurrency = useAppSelector(function (s) { return (s.user && s.user.profile && s.user.profile.currency) || "AED"; });
  const cityOptions = useMemo(function () {
    const rk = form.region || "AE";
    return serverCityOptions(geo, rk, language) || citiesOfCountry(rk, language);
  }, [geo, form.region, language]);

  useEffect(function () {
    if (serverAppliedCk) return;
    if (!serverDetails && !hasSaved) return;
    setForm(function (prev) {
      const next = Object.assign({}, prev);
      /* ★ صفّ مؤقت (عميل/جديد/…)؟ لا يُعبَّأ — تبقى الحقول فارغة */
      if (serverDetails && !isNewCustomerProfile(serverDetails)) {
        if (!next.firstName && serverDetails.firstName) next.firstName = serverDetails.firstName;
        if (!next.lastName && serverDetails.lastName) next.lastName = serverDetails.lastName;
        if (serverDetails.phoneNumber) {
          const parts = splitPhone(serverDetails.phoneNumber, "971");
          if (!next.phone) next.phone = parts.local;
        }
      }
      const first = serverLocations.filter(function (l) { return !!l.isDefault; })[0] || serverLocations[0];
      if (first) {
        if (!next.city && (first.cityName || first.city)) next.city = cityAr(first.cityName || first.city);
        if (!next.district && first.area) next.district = first.area;
        if (!next.street && first.street) next.street = first.street;
        if (!next.building && (first.buildingName || first.buildingNumber)) next.building = first.buildingName || first.buildingNumber;
        if (!next.postal && first.zipCode) next.postal = first.zipCode;
        if (!next.notes && first.deliveryNote) next.notes = first.deliveryNote;
        if (first.countryId && (!next.region || next.region === "AE")) next.region = countryKeyOfId(first.countryId);
      }
      return next;
    });
    setServerAppliedCk(true);
    if (hasSaved) {
      setStep("pay");
      setInfoEdit(false);
    }
  }, [serverDetails, serverLocations, hasSaved, serverAppliedCk]);

  /* تعبئة الحقول الفارغة من الملف عند وصوله (بعد تسجيل الدخول) */
  const profileKey = String((profile && profile.firstName) || "") + "|" + String((profile && profile.lastName) || "") + "|" + String((profile && profile.phone) || "") + "|" + String((profile && profile.region) || "");
  const [seenProfile, setSeenProfile] = useState(profileKey);
  if (seenProfile !== profileKey) {
    setSeenProfile(profileKey);
    setForm(function (prev) {
      const next = Object.assign({}, prev);
      if (!next.firstName && profile.firstName) next.firstName = profile.firstName;
      if (!next.lastName && profile.lastName) next.lastName = profile.lastName;
      if (!next.phone && profile.phone) next.phone = profile.phone;
      if ((!next.region || next.region === "AE") && profile.region) next.region = profile.region;
      const a = (profile && profile.address) || {};
      ["city", "district", "street", "building", "postal", "notes"].forEach(function (k) {
        if (!next[k] && a[k]) next[k] = a[k];
      });
      if (!next.propertyType && a.propertyType) next.propertyType = a.propertyType;
      return next;
    });
  }

  const patch = useCallback(function (key, value) {
    setForm(function (prev) {
      const next = Object.assign({}, prev);
      next[key] = value;
      return next;
    });
    setErrors(function (prev) {
      if (!prev[key]) return prev;
      const next = Object.assign({}, prev);
      delete next[key];
      return next;
    });
  }, []);

  const flash = useCallback(
    function (text) {
      if (text) dispatch(uiActions.toastShown(text));
    },
    [dispatch]
  );

  /* الانتقال بين الخطوات: نتحقّق من كل ما سبقها (العنوان المحفوظ يُغني عن نموذج info) */
  function jumpTo(target) {
    if (target === step) return;
    if (target === "info" && hasSaved && !infoEdit) setInfoEdit(true);
    if (STEP_AT[target] > STEP_AT.info && infoNeeded) {
      const info = validateStep(form, "info");
      if (!info.valid) {
        setErrors(info.errors);
        setStep("info");
        flash(info.firstError);
        return;
      }
    }
    if (STEP_AT[target] > STEP_AT.pay) {
      const pay = validateStep(form, "pay");
      if (!pay.valid) {
        setErrors(pay.errors);
        setStep("pay");
        flash(pay.firstError);
        return;
      }
    }
    setErrors({});
    setStep(target);
    try {
      window.scrollTo(0, 0);
    } catch (e) {
      /* بيئة بلا نافذة */
    }
  }

  function nextFromInfo() {
    const res = validateStep(form, "info");
    if (!res.valid) {
      setErrors(res.errors);
      flash(res.firstError);
      return;
    }
    setErrors({});
    if (!customerId) {
      setStep("pay");
      return;
    }
    setSyncBusy(true);
    const phoneFull = joinPhone(phoneCodeOfRegion(form.region), form.phone);
    dispatch(saveProfileSmart({
      customerId: Number(customerId),
      firstName: cleanText(form.firstName),
      lastName: cleanText(form.lastName),
      phoneNumber: phoneFull
    })).unwrap().then(function () {
      return dispatch(saveLocationSmart({
        customerId: Number(customerId),
        form: {
          region: form.region,
          city: form.city,
          district: form.district,
          street: form.street,
          building: form.building,
          postal: form.postal,
          addressType: form.propertyType === "office" ? "work" : "home",
          notes: form.notes,
          isDefault: true
        }
      })).unwrap();
    }).then(function () {
      setSyncBusy(false);
      setInfoEdit(false);
      setStep("pay");
      try { window.scrollTo(0, 0); } catch (e) {}
    }, function (err) {
      setSyncBusy(false);
      /* ★ المدينة ليست في قائمة الخادم؟ نبقى في خطوة العنوان ونعرض
         رسالة الخادم (تذكر المدن المتاحة) — فالمتابعة ستُسقط العنوان */
      const msg = String((err && err.message) || "");
      if ((err && err.code === "ECITYUNKNOWN") || msg.indexOf("غير متوفرة في الخادم") !== -1) {
        flash(msg || "المدينة غير متوفرة في الخادم — اختر مدينة أخرى.");
        return;
      }
      setInfoEdit(false);
      setStep("pay");
      flash("حُفظت بياناتك محلياً وتعذّرت المزامنة مع الخادم");
    });
  }

  function nextFromPay() {
    const res = validateStep(form, "pay");
    if (!res.valid) {
      setErrors(res.errors);
      flash(res.firstError);
      return;
    }
    setErrors({});
    setStep("review");
  }

  /* تأكيد الدفع: تحقّق كامل ← طلب الخادم (أو فاتورة محلية احتياطاً) ← فاتورة.
     ★ عنوان محفوظ بلا تعديل؟ نتحقّق من الدفع والموافقة فقط — النموذج غير مطلوب. */
  function confirm() {
    let res;
    if (!infoNeeded) {
      const pay = validateStep(form, "pay");
      if (!pay.valid) {
        setErrors(pay.errors);
        setStep("pay");
        flash(pay.firstError);
        return;
      }
      if (form.agree !== true) {
        setErrors({ agree: "يجب الموافقة على الشروط قبل تأكيد الطلب." });
        setStep("review");
        flash("يجب الموافقة على الشروط قبل تأكيد الطلب.");
        return;
      }
      res = { valid: true, errors: {} };
    } else {
      res = validateStep(form, "review");
      if (!res.valid) {
        setErrors(res.errors);
        const keys = Object.keys(res.errors);
        const bad = keys.indexOf("agree") !== -1 ? "review" : keys.some(function (k) { return PAY_KEYS.indexOf(k) !== -1; }) ? "pay" : "info";
        setStep(bad);
        flash(res.firstError);
        return;
      }
    }

    setBusy(true);
    function customerObj() {
      const srv = serverLocations.filter(function (l) { return !!l.isDefault; })[0] || serverLocations[0] || {};
      return {
        firstName: cleanText(form.firstName) || cleanText(serverDetails && serverDetails.firstName),
        lastName: cleanText(form.lastName) || cleanText(serverDetails && serverDetails.lastName),
        name: [cleanText(form.firstName) || cleanText(serverDetails && serverDetails.firstName), cleanText(form.lastName) || cleanText(serverDetails && serverDetails.lastName)].filter(Boolean).join(" "),
        phone: cleanText(form.phone) || cleanText(serverDetails && serverDetails.phoneNumber),
        region: cleanText(form.region) || countryKeyOfId(srv.countryId) || "AE",
        city: cleanText(form.city),
        district: cleanText(form.district) || cleanText(srv.area),
        street: cleanText(form.street) || cleanText(srv.street),
        building: cleanText(form.building) || cleanText(srv.buildingName || srv.buildingNumber),
        postal: cleanText(form.postal) || cleanText(srv.zipCode),
        propertyType: cleanText(form.propertyType),
        notes: cleanText(form.notes) || cleanText(srv.deliveryNote)
      };
    }
    /* فاتورة محلية (احتياط بلا خادم) — نفس السلوك القديم */
    function buildLocalBill() {
      /* مهلة قصيرة تُحاكي نداء بوابة الدفع — مع مؤشّر تحميل واضح */
      window.setTimeout(function () {
      const built = dispatch(
        placeOrder({
          method: form.method,
          customer: customerObj(),
          payment: {},
          agree: form.agree === true
        })
      );
      setBusy(false);
      if (built) {
        setOrder(built);
        setErrors({});
        try {
          window.scrollTo(0, 0);
        } catch (e) {
          /* تجاهل */
        }
      }
      }, 900);
    }
    /* ★ بطاقة/محفظة (فيزا/ماستركارد/Apple Pay…) تُدفع عبر صفحة PayTabs
       المستضافة — أما النقدي/الحوالة فطلب مباشر بلا بوابة. */
    function isOnlineKind() {
      const k = kindOf(form.method);
      return k === "card" || k === "wallet";
    }
    /* ★ بطاقة/محفظة (فيزا/ماستركارد/Apple Pay…) تُدفع عبر صفحة PayTabs
       المستضافة — لكن المغادرة لا تتم من هنا مباشرة: ننتقل أولاً إلى
       صفحة التوجيه #/payment/start (تصميمنا + «تم توجيهك… انتظر قليلاً»)
       وهي التي تنشئ الطلب ثم تبدأ الدفع (start ← orderId) وتغادر إلى
       paymentUrl — فإن تعذّر أي نداء بقي العميل داخل الموقع على شاشة
       خطأ واضحة بدل التعليق. */
    function startOnlineSession(orderFields) {
      savePaymentSetup({
        customerId: Number(customerId),
        method: form.method,
        customer: customerObj(),
        orderFields: orderFields,
        startedAt: Date.now()
      });
      setBusy(false);
      navigate(PATHS.paymentStart);
    }
    /* ★ طلب الخادم: POST /api/orders/{customerId} بمعاملة واحدة
       (سلة بالأسعار اللحظية + إعادة فحص الكوبون + فاتورة + إفراغ السلة).
       الكوبون الساقط لحظة الطلب (400 + reason): نُسقطه ونبقى للمراجعة. */
    function buildServerBill() {
      const loc = serverLocations.filter(function (l) { return !!l.isDefault; })[0] || serverLocations[0] || null;
      const locationId = loc ? (loc.locationId != null ? loc.locationId : loc.id) : null;
      let paymentMethodId = 0;
      (payItems || []).forEach(function (m) {
        if (m && m.key === form.method) paymentMethodId = Number(m.id) || 0;
      });
      const deliveryMethodId = carrier ? Number(carrier.id) : 0;
      /* معرّف ناقص (قوائم الخادم لم تصل)؟ فاتورة محلية بدل طلب مكسور */
      if (!customerId || !locationId || !paymentMethodId || !deliveryMethodId) {
        buildLocalBill();
        return;
      }
      const meta = currencyMeta(profileCurrency);
      const orderFields = {
        locationId: locationId,
        deliveryMethodId: deliveryMethodId,
        paymentMethodId: paymentMethodId,
        couponCode: appliedCoupon || null,
        customerNote: cleanText(form.notes) || null,
        termsAccepted: true
      };
      /* ★ بطاقة/محفظة؟ ننتقل لصفحة التوجيه #/payment/start التي تنفّذ
         العقد (طلب ← start ← paymentUrl). لا فاتورة بعد — العربة تبقى
         وتُفرَّغ عند النجاح. */
      if (isOnlineKind()) {
        startOnlineSession(orderFields);
        return;
      }
      createServerOrder(Number(customerId), orderFields).then(function (srvBill) {
        const order = normalizeServerOrder(srvBill, {
          method: form.method,
          methodLabel: methodLabelOf(form.method, language),
          kind: kindOf(form.method),
          customer: customerObj(),
          currency: { key: meta.key, rate: meta.rate, decimals: meta.decimals, symbol: meta.symbol, symbolEn: meta.symbolEn, position: meta.position }
        });
        dispatch(ordersActions.orderPlaced(order));
        dispatch(cartActions.clearCart());
        try {
          clearServerBasket(Number(customerId));
        } catch (e) {}
        setBusy(false);
        setOrder(order);
        setErrors({});
        try {
          window.scrollTo(0, 0);
        } catch (e) {
          /* تجاهل */
        }
      }, function (err) {
        setBusy(false);
        const data = err && err.response && err.response.data;
        /* ★ detail العربية أولاً — title العام (conflict/...) يُخفي المعنى */
        const srvMsg = data && (data.detail || data.message || data.error || data.title) ? String(data.detail || data.message || data.error || data.title) : "";
        const reason = data && data.reason ? String(data.reason).toUpperCase() : "";
        /* ★ وحده الكوبون الساقط يُسقط الكوبون — المخزون/التحقق يعرض
           رسالة الخادم الكاملة مع إرشاد تخفيض الكمية (لا تُمسّ الكوبون). */
        const couponReasons = ["NOT_FOUND", "INACTIVE", "EXPIRED", "NOT_STARTED", "MIN_SUBTOTAL", "MIN_ITEMS", "USAGE_LIMIT", "USAGE_PER_CUSTOMER", "EMPTY_BASKET", "COUPON"];
        const isCoupon = couponReasons.some(function (r) {
          return reason.indexOf(r) !== -1;
        });
        if (err && err.status === 400 && isCoupon) {
          dispatch(cartActions.removeCoupon());
          flash(srvMsg || "سقط الكوبون لحظة الطلب — أُكمل بلا خصم أو جرّب كوداً آخر.");
          return;
        }
        if (err && err.status === 400) {
          /* ★ الدفع عند الاستلام موقوف (§9) = اختر إلكترونية — لا علاقة له بالمخزون */
          if (/موقوف|معطّل|الدفع عند الاستلام/i.test(srvMsg)) {
            flash((srvMsg || "الدفع عند الاستلام موقوف حالياً.") + " — اختر طريقة دفع إلكترونية (بطاقة/محفظة) لإتمام طلبك.");
            return;
          }
          const parsed = parseAvailability(srvMsg);
          const who = parsed && parsed.productId != null
            ? "المنتج " + parsed.productId
            : parsed && parsed.productName
              ? "«" + parsed.productName + "»"
              : "";
          const hint =
            parsed && parsed.available != null
              ? who
                ? " — " + who + ": الكمية المتاحة " + parsed.available + ". خفّض إليها في العربة ثم أعد المحاولة."
                : " — الكمية المتاحة " + parsed.available + ". خفّض إليها في العربة ثم أعد المحاولة."
              : " — خفّض كمية السلة إلى المتاح (راجع DevTools ← Response للنص الكامل) ثم أعد المحاولة.";
          flash((srvMsg || "تعذّر إنشاء الطلب.") + hint);
          return;
        }
        flash(srvMsg || "تعذّر إرسال الطلب — تحقق من الاتصال وحاول مجدداً.");
      });
    }
    /* ★ كوبون مطبق؟ نُعيد التحقق أولاً (بصمت) — فالساقط يسقط خصمه
       ويُبنى الطلب على الأرقام الطازجة، والدفع لا يُمنع أبداً */
    function afterCoupon() {
      if (customerId) buildServerBill();
      else buildLocalBill();
    }
    if (appliedCoupon && customerId) {
      dispatch(validateCouponCode(appliedCoupon, { silent: true })).then(afterCoupon, afterCoupon);
    } else {
      afterCoupon();
    }
  }

  function printInvoice() {
    try {
      document.body.classList.add("ck-print");
      window.print();
      window.setTimeout(function () {
        document.body.classList.remove("ck-print");
      }, 400);
    } catch (e) {
      /* متصفّح بلا طباعة */
    }
  }

  function downloadInvoice() {
    if (!order) return;
    const money = makeMoneyFrom(order.currency, language);
    const lines = [];
    lines.push(tr2(language, "Atyab Al-Jasem — perfumes & bakhoor", "أطياب الجاسم — العطور والبخور"));
    lines.push(tr2(language, "Invoice number #", "فاتورة رقم #") + order.invoiceNo);
    lines.push(shortDate(order.createdAt) + " · " + shortTime(order.createdAt));
    lines.push(tr2(language, "Status: ", "الحالة: ") + T(ORDER_STATUS_LABEL, language));
    lines.push("");
    lines.push(tr2(language, "Deliver to: ", "التوصيل إلى: ") + ([order.customer.firstName, order.customer.lastName].filter(Boolean).join(" ") || order.customer.name) + " · " + order.customer.phone);
    lines.push([order.customer.region, order.customer.city, order.customer.district, order.customer.street, order.customer.building, order.customer.postal].filter(Boolean).join(" · "));
    if (order.customer.propertyType) lines.push(tr2(language, "Property type: ", "نوع العقار: ") + propertyLabelOf(order.customer.propertyType));
    lines.push("");
    order.items.forEach(function (item) {
      lines.push("- " + orderItemName(item, language) + " × " + item.qty + " = " + money.format(item.lineTotal));
    });
    lines.push("");
    lines.push(tr2(language, "Subtotal: ", "المجموع الفرعي: ") + money.format(order.totals.before));
    if (order.totals.offerSave > 0) lines.push(tr2(language, "Offer discount: - ", "خصم العروض: - ") + money.format(order.totals.offerSave));
    if (order.totals.discount > 0) {
      lines.push(tr2(language, "Coupon ", "كوبون ") + order.totals.code + ": - " + money.format(order.totals.discount));
    }
    lines.push(tr2(language, "Shipping: ", "الشحن: ") + money.format(order.totals.shipping));
    lines.push(tr2(language, "VAT (" + Math.round(((order.totals.vatRate == null ? 0.05 : order.totals.vatRate)) * 100) + "%" + (order.totals.vatIncluded !== false ? ", included): " : ", added): "), "ضريبة القيمة المضافة (" + Math.round(((order.totals.vatRate == null ? 0.05 : order.totals.vatRate)) * 100) + "%" + (order.totals.vatIncluded !== false ? "، مضمّنة): " : "، تُضاف): ")) + money.format(order.totals.vat));
    lines.push(tr2(language, "Total: ", "الإجمالي: ") + money.format(order.totals.total));
    lines.push("");
    lines.push(tr2(language, "Payment method: ", "طريقة الدفع: ") + methodText(order, language));
    if (order.terms && order.terms.version) {
      lines.push(tr2(language, "Terms & conditions accepted — version ", "الشروط والأحكام: موافَق عليها — نسخة ") + order.terms.version);
    }
    lines.push("");

    try {
      const blob = new Blob([lines.join("\n")], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "invoice-" + order.invoiceNo + ".txt";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.setTimeout(function () {
        URL.revokeObjectURL(url);
      }, 4000);
      dispatch(uiActions.toastShown("تم تحميل نسخة الفاتورة"));
    } catch (e) {
      flash("تعذّر تحميل الفاتورة");
    }
  }

  /* ---------- فاتورة جاهزة (بعد تأكيد الطلب) ---------- */
  if (order) {
    return (
      <section className="container view ck ct" id="checkoutView">
        <header className="ck-done-head">
          <span className="ck-done-ic">
            <Icon name="check" strokeWidth={2.6} />
          </span>
          <span className="eyebrow">تم الطلب</span>
          <h1>
            شكراً لك — <span className="gold-text">طلبك مُسجَّل</span>
          </h1>
          <p className="ck-done-sub">
            حفظنا فاتورتك برقم <b>#{order.invoiceNo}</b>، وأفرغنا العربة. الفاتورة أدناه جاهزة للطباعة أو للتحميل.
          </p>
        </header>

        <div className="ck-done-actions">
          <button className="btn-primary" type="button" onClick={printInvoice}>
            <Icon name="print" strokeWidth={1.8} />
            <span>طباعة الفاتورة</span>
          </button>
          <button className="btn-ghost" type="button" onClick={downloadInvoice}>
            <Icon name="doc" strokeWidth={1.8} />
            <span>تحميل نسخة نصّية</span>
          </button>
          <Link className="btn-ghost" to={PATHS.profile}>
            <Icon name="doc" strokeWidth={1.8} />
            <span>طلباتي</span>
          </Link>
          <Link className="btn-ghost" to={PATHS.perfumes}>
            <Icon name="cart" strokeWidth={1.8} />
            <span>متابعة التسوق</span>
          </Link>
        </div>

        <Invoice order={order} language={language} />
      </section>
    );
  }

  /* ---------- العربة فارغة ---------- */
  if (totals.count === 0) {
    return (
      <section className="container view ck ct" id="checkoutView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="cart" strokeWidth={1.6} />
          </span>
          <h3>لا يوجد ما يُدفع</h3>
          <p>العربة فارغة — أضف عطراً أو بخوراً ثم عُد إلى هنا لإتمام الطلب.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.perfumes}>
              تصفّح العطور
            </Link>
            <Link className="btn-ghost" to={PATHS.incense}>
              تصفّح البخور
            </Link>
          </div>
        </div>
      </section>
    );
  }

  const kind = kindOf(form.method);
  const fullName = [cleanText(form.firstName), cleanText(form.lastName)].filter(Boolean).join(" ");

  /* ---------- تسجيل الدخول أولاً: نموذج التوصيل للأعضاء فقط،
     والبريد معروف من الحساب — وزر التسجيل مختفي بحكم تسجيل الدخول. */
  if (!session) {
    return (
      <section className="container view ck ct" id="checkoutView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="user" strokeWidth={1.6} />
          </span>
          <h3>سجّل الدخول أولاً لإتمام طلبك</h3>
          <p>بيانات التوصيل والدفع تظهر للأعضاء فقط — سجّل الدخول أو أنشئ حساباً ببريدك، ثم عُد إلى هنا.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.login} state={{ from: PATHS.checkout }}>
              تسجيل الدخول
            </Link>
            <Link className="btn-ghost" to={PATHS.register} state={{ from: PATHS.checkout }}>
              إنشاء حساب جديد
            </Link>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className="container view ck ct" id="checkoutView">
      <div className="ct-top">
        <Link className="ct-back" to={PATHS.cart}>
          <Icon name="back" strokeWidth={2} />
          <span>رجوع إلى العربة</span>
        </Link>
        <span className="ct-crumb">
          الرئيسية / عربة التسوق / <b>إتمام الدفع</b>
        </span>
      </div>

      <header className="ct-head">
        <span className="eyebrow">الدفع</span>
        <h1>
          إتمام <span className="gold-text">الدفع</span>
        </h1>
        <p className="ct-sub">
          {infoNeeded
            ? "ثلاث خطوات: بياناتك، ثم طريقة الدفع، ثم مراجعة الفاتورة. لا نطلب أي بيانات بطاقة هنا — تختار الطريقة فقط، ولا يُخصم أي مبلغ في هذه النسخة التجريبية."
            : "خطوتان: طريقة الدفع، ثم مراجعة الفاتورة — التوصيل سيكون إلى عنوانك المحفوظ. لا نطلب أي بيانات بطاقة هنا."}
        </p>
      </header>

      <StepRail step={step} steps={visibleSteps} onJump={jumpTo} />
      {!infoNeeded ? (
        <div className="ct-card ck-card ck-saved-addr">
          <h3 className="ck-card-title">
            <Icon name="truck" strokeWidth={1.8} />
            <span>التوصيل سيكون إلى هذا العنوان</span>
          </h3>
          <p className="ck-card-sub">
            {[serverLocations[0] && serverLocations[0].area, serverLocations[0] && serverLocations[0].street, serverLocations[0] && (serverLocations[0].buildingName || serverLocations[0].buildingNumber)].filter(Boolean).join(" · ") || "عنوانك المحفوظ"}
            {serverLocations[0] && serverLocations[0].zipCode ? " · " + serverLocations[0].zipCode : ""}
          </p>
          <button className="ck-edit" type="button" onClick={function () { setInfoEdit(true); setStep("info"); }}>
            تعديل بيانات التوصيل
          </button>
        </div>
      ) : null}

      <div className="ck-grid">
        <div className="ck-main">
          {/* -------- ١) بيانات التوصيل -------- */}
          {step === "info" && infoNeeded ? (
            <div className="ct-card ck-card">
              <h3 className="ck-card-title">
                <Icon name="truck" strokeWidth={1.8} />
                <span>بيانات التوصيل</span>
              </h3>
              <p className="ck-card-sub">العنوان الوطني يساعد المندوب على الوصول من أول مرة.</p>

              <div className="ck-fields">
                <Field
                  id="ckFirstName"
                  label="الاسم الأول"
                  required
                  value={form.firstName}
                  error={errors.firstName}
                  placeholder="مثال: عبدالله"
                  autoComplete="given-name"
                  onChange={function (v) { patch("firstName", v); }}
                />
                <Field
                  id="ckLastName"
                  label="الاسم الثاني"
                  required
                  value={form.lastName}
                  error={errors.lastName}
                  placeholder="مثال: الجاسم"
                  autoComplete="family-name"
                  onChange={function (v) { patch("lastName", v); }}
                />
                <Field
                  id="ckPhone"
                  label="رقم الجوال"
                  required
                  type="tel"
                  inputMode="tel"
                  dir="ltr"
                  value={form.phone}
                  error={errors.phone}
                  placeholder="5xxxxxxxx"
                  onChange={function (v) { patch("phone", v); }}
                />
                <Field
                  id="ckRegion"
                  label="الدولة"
                  required
                  tag="select"
                  value={form.region || "AE"}
                  error={errors.region}
                  placeholder="— اختر الدولة —"
                  options={(ATYAB_COUNTRIES || []).map(function (c) {
                    return { key: c.key, label: language === "en" ? c.labelEn || c.label : c.label };
                  })}
                  onChange={function (v) {
                    const next = v || "AE";
                    const keys = (serverCityOptions(geo, next, "ar") || citiesOfCountry(next, "ar")).map(function (m) { return m.key; });
                    if (form.city && keys.length && keys.indexOf(form.city) === -1) patch("city", "");
                    patch("region", next);
                  }}
                />
                <Field
                  id="ckCity"
                  label="المدينة"
                  required
                  tag="select"
                  value={form.city}
                  error={errors.city}
                  placeholder="— اختر المدينة —"
                  options={cityOptions}
                  onChange={function (v) { patch("city", v); }}
                />
                <Field
                  id="ckDistrict"
                  label="المنطقة"
                  required
                  value={form.district}
                  error={errors.district}
                  placeholder="مثال: المارينا"
                  onChange={function (v) { patch("district", v); }}
                />
                <Field
                  id="ckStreet"
                  label="الشارع"
                  value={form.street}
                  error={errors.street}
                  placeholder="مثال: شارع الشيخ زايد"
                  onChange={function (v) { patch("street", v); }}
                />
                <Field
                  id="ckBuilding"
                  label="اسم المبنى"
                  required
                  value={form.building}
                  error={errors.building}
                  placeholder="مثال: برج السلام، شقة 1204"
                  onChange={function (v) { patch("building", v); }}
                />
                <Field
                  id="ckPostal"
                  label="الرمز البريدي"
                  inputMode="text"
                  dir="ltr"
                  value={form.postal}
                  error={errors.postal}
                  placeholder="اختياري"
                  onChange={function (v) { patch("postal", v); }}
                />
                <Field
                  id="ckPropertyType"
                  label="نوع العقار"
                  required
                  tag="select"
                  value={form.propertyType}
                  error={errors.propertyType}
                  placeholder="— اختر نوع العقار —"
                  options={PROPERTY_TYPES.map(function (p) {
                    return { key: p.key, label: p.label };
                  })}
                  onChange={function (v) { patch("propertyType", v); }}
                />
                <Field
                  id="ckNotes"
                  label="ملاحظات للمندوب"
                  wide
                  value={form.notes}
                  error={errors.notes}
                  placeholder="مثال: البوابة الثانية، الاتصال قبل الوصول"
                  onChange={function (v) { patch("notes", v); }}
                />
              </div>

              <div className="ck-actions">
                <button className="btn-primary" type="button" onClick={nextFromInfo} disabled={syncBusy}>
                  <span>{syncBusy ? "يُحفظ…" : "التالي: طريقة الدفع"}</span>
                  <Icon name="chevLeft" strokeWidth={2} />
                </button>
                <span className="ck-actions-note">
                  <Icon name="lock" strokeWidth={1.8} />
                  <span>بياناتك بأمان ولا تُستخدم إلا لإتمام طلبك.</span>
                </span>
              </div>
            </div>
          ) : null}

          {/* -------- ٢) طريقة الدفع -------- */}
          {step === "pay" ? (
            <div className="ct-card ck-card">
              <h3 className="ck-card-title">
                <Icon name="card" strokeWidth={1.8} />
                <span>طريقة الدفع</span>
              </h3>
              <p className="ck-card-sub">اختر الطريقة فقط — لا نطلب أي بيانات بطاقة هنا.</p>

              <CouponBox id="ckCouponInput" />

              <MethodPicker
                name="ckPay"
                value={form.method}
                onChange={function (key) {
                  patch("method", key);
                  dispatch(cartActions.setPaymentMethod(key));
                }}
              />
              {errors.method ? (
                <p className="ck-err ck-err-block">
                  <Icon name="alert" strokeWidth={2} />
                  <span>{errors.method}</span>
                </p>
              ) : null}

              {/* ★ شركة التوصيل من الخادم (أول شركة) — تُرسل كـ deliveryMethodId
                 مع الطلب، وتظهر أجرتها الفعلية في فاتورة الخادم */}
              {carrier ? (
                <div className="ck-note-box">
                  <Icon name="truck" strokeWidth={1.8} />
                  <div>
                    <b>التوصيل عبر {carrier.name}</b>
                    <span>{carrier.phone ? " · " + carrier.phone : ""}{carrier.email ? " · " + carrier.email : ""}</span>
                  </div>
                </div>
              ) : null}

              {/* لا حقول بطاقة إطلاقاً — الاختيار فقط، ثم تُستكمل
                 البيانات عند الدفع الفعلي عبر البوابة. */}
              {kind === "card" || kind === "wallet" ? (
                <div className="ck-note-box">
                  <Icon name="shield" strokeWidth={1.8} />
                  <div>
                    <b>لا نطلب بيانات البطاقة هنا</b>
                    <span>اخترت «{methodLabelOf(form.method, language) || form.method}» — ستُحوَّل إلى البوابة الآمنة عند تفعيل الدفع الفعلي، ولا نحفظ أي رقم بطاقة.</span>
                  </div>
                </div>
              ) : null}

              {/* حوالة بنكية */}
              {kind === "transfer" ? (
                <div className="ck-transfer">
                  <ul className="ck-bank">
                    <li>
                      <span>البنك</span>
                      <b>{T(TRANSFER_BANK.bank, language)}</b>
                    </li>
                    <li>
                      <span>اسم الحساب</span>
                      <b>{T(TRANSFER_BANK.holder, language)}</b>
                    </li>
                    <li>
                      <span>رقم الآيبان</span>
                      <b dir="ltr">{formatIban(TRANSFER_BANK.iban)}</b>
                    </li>
                    <li>
                      <span>رقم الحساب</span>
                      <b dir="ltr">{TRANSFER_BANK.account}</b>
                    </li>
                  </ul>
                  <p className="ck-hint">{T(TRANSFER_BANK.note, language)}</p>
                  <label className={"ck-check ck-check-block" + (errors.transferAck ? " is-bad" : "")}>
                    <input
                      type="checkbox"
                      checked={form.transferAck === true}
                      onChange={function (e) {
                        patch("transferAck", e.target.checked);
                      }}
                    />
                    <span>سأحوّل مبلغ الفاتورة إلى الحساب أعلاه وأُرسل إشعار الحوالة.</span>
                  </label>
                  {errors.transferAck ? (
                    <p className="ck-err">
                      <Icon name="alert" strokeWidth={2} />
                      <span>{errors.transferAck}</span>
                    </p>
                  ) : null}
                </div>
              ) : null}

              {/* عند الاستلام */}
              {kind === "cod" ? (
                <div className="ck-note-box">
                  <Icon name="cash" strokeWidth={1.8} />
                  <div>
                    <b>الدفع عند الاستلام</b>
                    <span>جهّز المبلغ نقداً للمندوب. قد نتواصل معك هاتفياً لتأكيد العنوان قبل الخروج.</span>
                  </div>
                </div>
              ) : null}

              <div className="ck-demo">
                <Icon name="info" strokeWidth={1.8} />
                <span>{(kind === "card" || kind === "wallet") ? T(PAY_REDIRECT_NOTE, language) : T(DEMO_NOTICE, language)}</span>
              </div>

              <div className="ck-actions">
                <button className="btn-ghost" type="button" onClick={function () { jumpTo("info"); }}>
                  <Icon name="chevRight" strokeWidth={2} />
                  <span>السابق</span>
                </button>
                <button className="btn-primary" type="button" onClick={nextFromPay}>
                  <span>التالي: المراجعة</span>
                  <Icon name="chevLeft" strokeWidth={2} />
                </button>
              </div>
            </div>
          ) : null}

          {/* -------- ٣) المراجعة والتأكيد -------- */}
          {step === "review" ? (
            <div className="ct-card ck-card">
              <h3 className="ck-card-title">
                <Icon name="check" strokeWidth={1.8} />
                <span>المراجعة والتأكيد</span>
              </h3>
              <p className="ck-card-sub">تأكّد من بياناتك وطريقة الدفع قبل إصدار الفاتورة.</p>

              <div className="ck-review">
                <div className="ck-review-block">
                  <h4>
                    <Icon name="truck" strokeWidth={1.8} />
                    <span>التوصيل</span>
                  </h4>
                  <p>
                    <b>{fullName}</b> · {form.phone} · {countryName(form.region, language)}
                  </p>
                  <p>
                    {[form.city, form.district, form.street, form.building, form.postal].filter(Boolean).join(" · ")}
                  </p>
                  {form.propertyType ? (
                    <p className="ck-hint">نوع العقار: {propertyLabelOf(form.propertyType)}</p>
                  ) : null}
                  <button className="ck-edit" type="button" onClick={function () { jumpTo("info"); }}>
                    تعديل البيانات
                  </button>
                </div>

                <div className="ck-review-block">
                  <h4>
                    {kind === "card" ? <Icon name="card" strokeWidth={1.8} /> : null}
                    {kind === "wallet" ? <Icon name="wallet" strokeWidth={1.8} /> : null}
                    {kind === "transfer" ? <Icon name="bank" strokeWidth={1.8} /> : null}
                    {kind === "cod" ? <Icon name="cash" strokeWidth={1.8} /> : null}
                    <span>طريقة الدفع</span>
                  </h4>
                  <p>
                    <b>{methodLabelOf(form.method, language) || "—"}</b>
                  </p>
                  <button className="ck-edit" type="button" onClick={function () { jumpTo("pay"); }}>
                    تعديل طريقة الدفع
                  </button>
                </div>
              </div>

              {/* ★ الشروط والأحكام: زر «مثل اعرف قصته» يفتح نافذة بالنصّ
                 الكامل، وتحته زر الموافقة مفعّل مسبقاً. رقم النسخة يُسجَّل
                 مع الطلب (terms) لأغراض التوثيق. */}
              <div className={"ck-terms" + (errors.agree ? " is-bad" : "")}>
                <div className="ck-terms-head">
                  <Icon name="doc" strokeWidth={1.7} />
                  <b>الشروط والأحكام</b>
                  <span className="ck-terms-ver">
                    نسخة {ATYAB_TERMS.version} · {T(ATYAB_TERMS.updated, language)}
                  </span>
                </div>

                {/* ★ الشروط: زر «اقرأ الشروط والأحكام» يفتح نافذة بالنصّ
                   الكامل، وتحته زر الموافقة مفعّل مسبقاً — لا نصّ ظاهر دائماً. */}
                <button
                  className="pd-more ck-terms-btn"
                  type="button"
                  onClick={function () {
                    setTermsOpen(true);
                  }}
                >
                  <Icon name="spark" strokeWidth={1.6} />
                  <span>اقرأ الشروط والأحكام</span>
                </button>

                <label className="ck-check ck-check-agree">
                  <input
                    type="checkbox"
                    checked={form.agree === true}
                    onChange={function (e) {
                      patch("agree", e.target.checked);
                    }}
                  />
                  <span>أوافق على الشروط والأحكام وسياسة الاستبدال والخصوصية، وأتعهّد بصحّة البيانات أعلاه.</span>
                </label>
              </div>
              {errors.agree ? (
                <p className="ck-err">
                  <Icon name="alert" strokeWidth={2} />
                  <span>{errors.agree}</span>
                </p>
              ) : null}

              <div className="ck-paytotal">
                <span>الإجمالي المستحق</span>
                <b>
                  <Money sar={totals.total} />
                </b>
              </div>

              <button className="btn-primary ck-confirm" type="button" disabled={busy} onClick={confirm}>
                {busy ? (
                  <>
                    <span className="ck-spin" aria-hidden="true" />
                    <span>نُجهّز طلبك…</span>
                  </>
                ) : (
                  <>
                    <Icon name="lock" strokeWidth={1.9} />
                    <span>{kind === "card" || kind === "wallet" ? "المتابعة إلى الدفع الآمن" : "تأكيد الدفع"}</span>
                  </>
                )}
              </button>

              <p className="ck-actions-note">
                <Icon name="info" strokeWidth={1.8} />
                <span>{kind === "card" || kind === "wallet" ? "سيُخصم المبلغ في صفحة الدفع الآمنة فقط — وبعدها تصلك الفاتورة مدفوعة." : "لن تُخصم أي مبالغ — الفاتورة تُسجَّل وتصلنا، وتسددها بالطريقة المختارة."}</span>
              </p>
            </div>
          ) : null}
        </div>

        <aside className="ck-aside">
          <OrderSummary totals={totals} />
        </aside>
      </div>
      {termsOpen ? <TermsModal language={language} onClose={function () { setTermsOpen(false); }} /> : null}
    </section>
  );
}
