/* ============================================================
   أطياب الجاسم (React) — مترجم الواجهة الكامل (uiTranslate)

   الفكرة (كما في src/i18n.js القديم بالضبط): نصوص الواجهة تُكتب
   عربيةً داخل الكومبوننتات مباشرةً، وطبقة واحدة تترجمها إلى الإنجليزية
   حين تكون لغة الواجهة «en» — بدل تكرار الشرط في كل ملف.

   ★ كيف تعمل:
       1. نبني تعبيراً نمطياً واحداً من مفاتيح قاموس PHRASES (i18n.js)
          مرتّبةً من الأطول إلى الأقصر.
       2. نمشي على عُقد النصوص في الصفحة ونستبدل أي عبارة عربية موجودة
          بترجمتها — فيُترجَم النصّ حتى لو كان جزءاً من جملة أطول
          (مثل: «إزالة «عود الليل» من العربة»).
       3. نترجم أيضاً السمات المرئية: title · aria-label · placeholder · alt.
       4. النصوص الأصلية تُحفَظ في WeakMap، فإذا رجع العميل إلى العربية
          تُستعاد حرفياً بلا فقدان أي شيء.

   ★ لماذا المراقب (MutationObserver)؟ لأن React يعيد رسم النصّ العربي
     عند أي تحديث، فنُعيد الترجمة بعده. والتمريرة تتوقّف من نفسها حين
     لا يبقى نصّ عربي — فلا حلقة لا نهائية.
   ★ ما لا يُترجَم هنا: أسماء المنتجات ووصفها وقصصها — فهي «بيانات
     منتجات» تُقرأ من ملف البيانات (nameEn/descEn/storyEn) ويترجمها
     الكومبوننت نفسه؛ وهذا ما يُقابل عمود الترجمة في قاعدة البيانات.
   ============================================================ */

import { useEffect } from "react";
import { PHRASES } from "./i18n.js";

const SKIP_TAGS = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, INPUT: 1, CODE: 1, PRE: 1, SAMP: 1 };

/* الأحرف العربية (نطاق أساسي + ملحقات) */
const AR_RE = /[\u0600-\u06FF\u0750-\u077F\uFB50-\uFDFF\uFE70-\uFEFF]/;

/* حدود الكلمة: لا نطابق عبارة داخل كلمةٍ أطول (مثال: «من» لا تُطابق داخل
   «تمنح»، و«نسخ» لا تُطابق داخل «نسخة») — وهذا ما يجعل العبارات القصيرة آمنة */
const BR = "\\u0600-\\u06FF\\u0750-\\u077F\\uFB50-\\uFDFF\\uFE70-\\uFEFF";

const ATTRS = ["title", "aria-label", "placeholder", "alt"];

/* سجلّ كل عقدة/سمة: النصّ العربي الأصلي + النصّ الإنجليزي الذي كتبناه
   ★ نحفظ «ما كتبناه» أيضاً، لأن الرجوع إلى العربية يجب أن يمسّ فقط
     العُقد التي ما زالت تحمل ترجمتنا. فإن أعاد React رسم القيمة (مثلاً
     اسم منتج داخل aria-label تغيّر بتغيّر اللغة) فسجلّنا صار قديماً
     ويُسقَط بدل أن يطمس النصّ الصحيح الجديد. */
const ORIG_TEXT = new WeakMap(); /* Text → { ar, en } */
const ORIG_ATTR = new WeakMap(); /* Element → { attr: { ar, en } } */

let pattern = null;
let patternSize = 0;

function escapeRe(text) {
  return String(text).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function matcher() {
  const keys = Object.keys(PHRASES || {});
  if (pattern && patternSize === keys.length) return pattern;
  if (!keys.length) return null;
  keys.sort(function (a, b) {
    return b.length - a.length;
  });
  const body = keys.map(escapeRe).join("|");
  pattern = new RegExp("(?<![" + BR + "])(?:" + body + ")(?![" + BR + "])", "g");
  patternSize = keys.length;
  return pattern;
}

function translate(text) {
  const re = matcher();
  if (!re || !text || !AR_RE.test(text)) return text;
  return text.replace(re, function (hit) {
    const en = PHRASES[hit];
    return en != null ? en : hit;
  });
}

/* ------------------------------------------------------------
   الترجمة / الرجوع
   ------------------------------------------------------------ */
function translateTree() {
  const body = document.body;
  if (!body) return;

  const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, {
    acceptNode: function (node) {
      const parent = node.parentNode;
      if (!parent || SKIP_TAGS[parent.nodeName]) return NodeFilter.FILTER_REJECT;
      if (!node.nodeValue || !AR_RE.test(node.nodeValue)) return NodeFilter.FILTER_REJECT;
      /* محتوى العملاء (تعليقات/تقييمات) يُعلَّم بـdata-no-i18n فيبقى كما كتبه صاحبه */
      if (parent.closest && parent.closest("[data-no-i18n]")) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });

  let node = walker.nextNode();
  while (node) {
    const original = node.nodeValue;
    const en = translate(original);
    ORIG_TEXT.set(node, { ar: original, en: en });
    if (en !== original) node.nodeValue = en;
    node = walker.nextNode();
  }

  /* السمات المرئية */
  const els = body.querySelectorAll("[title], [aria-label], [placeholder], [alt]");
  Array.prototype.forEach.call(els, function (el) {
    if (el.closest && el.closest("[data-no-i18n]")) return;
    ATTRS.forEach(function (attr) {
      const value = el.getAttribute(attr);
      const box = ORIG_ATTR.get(el) || {};
      if (!value || !AR_RE.test(value)) {
        /* قيمة بلا حرف عربي: إمّا ترجمتنا نحن (فنُبقي السجلّ ونكمل)،
           وإمّا قيمة كتبها React من بيانات إنجليزية (فنسجلّنا قديم
           ويُسقَط حتى لا يطمسها الرجوع إلى العربية) */
        const rec = box[attr];
        if (rec && rec.en !== value) {
          delete box[attr];
          ORIG_ATTR.set(el, box);
        }
        return;
      }
      const en = translate(value);
      box[attr] = { ar: value, en: en };
      ORIG_ATTR.set(el, box);
      if (en !== value) el.setAttribute(attr, en);
    });
  });
}

function revertTree() {
  const body = document.body;
  if (!body) return;

  const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, null);
  let node = walker.nextNode();
  while (node) {
    const rec = ORIG_TEXT.get(node);
    if (rec) {
      /* نُرجع فقط إن كانت العقدة ما زالت تحمل ترجمتنا — وإلا فقد
         أعاد React رسمها بقيمة جديدة ونحن لا نملك حقّ طمسها */
      if (node.nodeValue === rec.en) node.nodeValue = rec.ar;
      ORIG_TEXT.delete(node);
    }
    node = walker.nextNode();
  }

  const els = body.querySelectorAll("[title], [aria-label], [placeholder], [alt]");
  Array.prototype.forEach.call(els, function (el) {
    const box = ORIG_ATTR.get(el);
    if (!box) return;
    ATTRS.forEach(function (attr) {
      const rec = box[attr];
      if (!rec) return;
      if (el.getAttribute(attr) === rec.en) el.setAttribute(attr, rec.ar);
      delete box[attr];
    });
  });
}

/* ------------------------------------------------------------
   الخطّاف: يُركَّب مرة واحدة في App
   ------------------------------------------------------------ */
export function useUiTranslation(language) {
  useEffect(
    function () {
      if (typeof document === "undefined") return undefined;
      const isEn = language === "en";

      if (!isEn) {
        revertTree();
        return undefined;
      }

      let frame = 0;
      function schedule() {
        if (frame) return;
        frame = window.requestAnimationFrame(function () {
          frame = 0;
          translateTree();
        });
      }

      schedule();

      const observer = new MutationObserver(schedule);
      observer.observe(document.body, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ATTRS
      });

      return function () {
        observer.disconnect();
        if (frame) window.cancelAnimationFrame(frame);
      };
    },
    [language]
  );
}

export { translate, revertTree, translateTree };
