/* ============================================================
   أطياب الجاسم (React) — شريحة الطلبات (ordersSlice)

   بعد ضغط العميل «تأكيد الدفع» يُبنى هنا «سجلّ طلب» كامل ومُجمَّد:
     · رقم الفاتورة وتاريخها بالملّي ثانية.
     · القطع وأسعارها لحظة الشراء (لا نقرأ السعر الحالي بعد اليوم —
       الفاتورة القديمة يجب أن تبقى كما طُبعت).
     · مجموع الفاتورة كما حُسب في selectors.js (خصم العروض · الكوبون ·
       الشحن · الضريبة · الإجمالي) + العملة التي كان العميل يراها.
     · بيانات التوصيل وطريقة الدفع (آخر ٤ أرقام فقط — لا رقم بطاقة كامل).
   ثم تُفرَّغ العربة، ويُحفظ الطلب في حساب العميل (ويُخزَّن محلياً أيضاً في
   atyab-orders كذاكرة تشغيل وليظهر فوراً في «طلباتي»).

   ★ الطلب يُسجَّل في حساب العميل على سيرفر المتجر (Order/OrderItems)،
     ومعه نسخة الشروط التي وافق عليها (TermsAcceptances). والنصّ الصريح في
     constants/payment.js يوضّح أن بوابة الدفع لم تُربط بعد.
   ★ الترتيب: الأحدث أولاً، وحدّ أقصى ٤٠ طلباً حتى لا تتضخّم الذاكرة.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { ATYAB_byId } from "../../data/products.js";
import { ATYAB_TERMS } from "../../data/appConfig.js";
import { KEYS, readJSON, writeJSON } from "../persist.js";
import { uiActions } from "./uiSlice.js";
import { cartActions, PAY_METHODS, serverCustomerId, clearServerBasket } from "./cartSlice.js";
import { selectCartTotals, currencyMeta, unitPriceOf } from "../selectors.js";
import { ORDER_STATUS_LABEL, ETA_DAYS, kindOf } from "../../constants/payment.js";

const MAX_ORDERS = 40;

export function methodLabelOf(key, language) {
  let found = null;
  PAY_METHODS.forEach(function (m) {
    if (m.key === key && m.key) found = m;
  });
  if (!found) return "";
  return language === "en" ? found.en || found.label : found.label;
}

/* اسم القطعة في الفاتورة: عربي أو إنجليزي حسب لغة العرض */
export function orderItemName(item, language) {
  if (!item) return "";
  if (language === "en" && item.nameEn) return item.nameEn;
  return item.name || "";
}

/* نافذة التسليم: تاريخ البداية والنهاية من مدّة التوصيل */
export function etaWindowOf(order) {
  const days = (order && order.eta) || ETA_DAYS;
  const start = Number(order && order.createdAt) || Date.now();
  const day = 86400e3;
  return { from: start + days.min * day, to: start + days.max * day, min: days.min, max: days.max };
}

function readOrders() {
  const arr = readJSON(KEYS.orders, []);
  if (!Array.isArray(arr)) return [];
  return arr.filter(function (o) {
    return o && typeof o === "object" && o.invoiceNo;
  }).slice(0, MAX_ORDERS);
}

function saveOrders(orders) {
  writeJSON(KEYS.orders, (orders || []).slice(0, MAX_ORDERS));
}

const slice = createSlice({
  name: "orders",
  initialState: { list: readOrders() },
  reducers: {
    orderPlaced: function (state, action) {
      const order = action.payload;
      if (!order || !order.invoiceNo) return;
      state.list = [order].concat(state.list).slice(0, MAX_ORDERS);
      saveOrders(state.list);
    },
    orderRemoved: function (state, action) {
      const invoiceNo = String(action.payload || "");
      state.list = state.list.filter(function (o) {
        return o.invoiceNo !== invoiceNo;
      });
      saveOrders(state.list);
    },
    ordersCleared: function (state) {
      state.list = [];
      saveOrders(state.list);
    }
  }
});

export const ordersActions = slice.actions;
export const ordersReducer = slice.reducer;

/* ------------------------------------------------------------
   الثَنَويّة الوحيدة: placeOrder
   تأخذ ما يُدخله العميل (الاسم · العنوان · الدفع) وتبني الطلب من
   الحالة نفسها — فتأتي الأرقام مطابقة تماماً للفاتورة التي رآها.
   ------------------------------------------------------------ */
export function placeOrder(input) {
  return function (dispatch, getState) {
    const state = getState();
    const rows = state.cart.rows || [];
    if (!rows.length) {
      const l = (state.ui && state.ui.language) || "ar";
      dispatch(uiActions.toastShown(l === "en" ? "The cart is empty — add an item first" : "العربة فارغة — أضف قطعة أولاً"));
      return null;
    }

    const totals = selectCartTotals(state);
    const meta = currencyMeta(state.user.profile.currency);
    const method = String((input && input.method) || state.cart.paymentMethod || "");
    const customer = (input && input.customer) || {};
    const payment = (input && input.payment) || {};
    const now = Date.now();
    const day = 86400e3;

    const order = {
      invoiceNo: state.cart.invoiceNo,
      createdAt: now,
      status: ORDER_STATUS_LABEL,
      method: method,
      methodLabel: methodLabelOf(method, (state.ui && state.ui.language) || "ar"),
      kind: kindOf(method),
      cardLast4: String(payment.cardLast4 || ""),
      walletPhone: String(payment.walletPhone || ""),
      customer: {
        firstName: String(customer.firstName || ""),
        lastName: String(customer.lastName || ""),
        name: String(customer.name || [customer.firstName, customer.lastName].filter(Boolean).join(" ")),
        phone: String(customer.phone || ""),
        region: String(customer.region || "AE"),
        city: String(customer.city || ""),
        district: String(customer.district || ""),
        street: String(customer.street || ""),
        building: String(customer.building || ""),
        postal: String(customer.postal || ""),
        propertyType: String(customer.propertyType || ""),
        landmark: String(customer.landmark || ""),
        notes: String(customer.notes || "")
      },
      items: totals.rows.map(function (row) {
        const product = ATYAB_byId ? ATYAB_byId(row.id) : null;
        return {
          id: row.id,
          name: (product && product.name) || "",
          nameEn: (product && product.nameEn) || "",
          image: (product && product.image) || "",
          qty: row.qty,
          unitPrice: unitPriceOf(product),
          lineTotal: row.lineTotal
        };
      }),
      totals: {
        count: totals.count,
        before: totals.before,
        offerSave: totals.offerSave,
        code: totals.code,
        percent: totals.percent,
        discount: totals.discount,
        shipping: totals.shipping,
        vat: totals.vat,
        /* ★ تُجمَّد نسبة الضريبة وطريقة احتسابها مع الفاتورة — فالفاتورة
           مستند لا يتغيّر حتى لو غيّر المالك الإعدادات لاحقاً */
        vatRate: totals.vatRate,
        vatIncluded: totals.vatIncluded,
        total: totals.total,
        saved: totals.saved
      },
      currency: {
        code: meta.key,
        rate: meta.rate,
        decimals: meta.decimals,
        symbol: meta.symbol,
        symbolEn: meta.symbolEn,
        position: meta.position
      },
      eta: { min: ETA_DAYS.min, max: ETA_DAYS.max, from: now + ETA_DAYS.min * day, to: now + ETA_DAYS.max * day },
      /* ★ توثيق الموافقة على الشروط: رقم النسخة + وقت الموافقة، يُحفظان مع
         الطلب ويظهران في الفاتورة (وفي قاعدة البيانات: TermsAcceptances). */
      terms: {
        accepted: !!(input && input.agree === true),
        version: (ATYAB_TERMS && ATYAB_TERMS.version) || "",
        acceptedAt: now
      }
    };

    dispatch(ordersActions.orderPlaced(order));
    dispatch(cartActions.clearCart());
    /* ★ عضو؟ سلة الخادم تُفرَّغ أيضاً بالمعرّف الحقيقي — فالطلب استلمها */
    try {
      const cid = serverCustomerId(getState);
      if (cid) clearServerBasket(cid);
    } catch (e) {}
    const lang = (state.ui && state.ui.language) || "ar";
    dispatch(uiActions.toastShown(lang === "en" ? "Your order is confirmed — thank you" : "تم تأكيد طلبك — شكراً لك"));
    return order;
  };
}

/* ------------------------------------------------------------ */
export const selectOrders = function (state) {
  return state.orders.list;
};
export const selectOrderCount = function (state) {
  return state.orders.list.length;
};
export const selectLatestOrder = function (state) {
  return state.orders.list[0] || null;
};
export const selectOrderByInvoice = function (state, invoiceNo) {
  const key = String(invoiceNo || "");
  return (
    state.orders.list.filter(function (o) {
      return o.invoiceNo === key;
    })[0] || null
  );
};
